options.func:
(async () => {
  if (arguments[0].value) {
    this.disabled(
      ["table_po." + arguments[0].rowIndex + ".tax_percent"],
      false
    );

    if (arguments[0].fieldModel) {
      this.setData({ ["table_po." + arguments[0].rowIndex + ".tax_percent"]: ''})
    }
  } else {
    this.disabled(
      ["table_po." + arguments[0].rowIndex + ".tax_percent"],
      true
    );

    this.setData({ ["table_po." + arguments[0].rowIndex + ".tax_percent"]: ''})
  }

  this.refreshFieldOptionData([`table_po.${arguments[0].rowIndex}.tax_percent`]);
})();
